edits:
[homing_override]
axes:xy
gcode: 

    M204 S10000
    M220 S100
[homing_override]
axes:xyz
gcode: 
    # q2-z-home-guard: 'G28 Z' on its own (no X, no Y) homes Z with the nozzle as the probe right
    # where the head stands. It is refused unless X and Y are homed and the nozzle is over the build
    # plate: X 0 to under 271, Y 5 to under 271 (PEI edges measured on a Q2 at about X-6, X278,
    # Y-1 and Y276, so at least 5 mm of plate around the nozzle). The head is never moved for it;
    # Home All (G28) is unchanged and still centres the head first. Messages are kept short so
    # they fit the printer screen's error box.
    {% set q2_zg_x_min = 0 %}
    {% set q2_zg_x_lim = 271 %}
    {% set q2_zg_y_min = 5 %}
    {% set q2_zg_y_lim = 271 %}
    {% if 'Z' in params and 'X' not in params and 'Y' not in params %}
        {% set q2_zg_pos = printer.toolhead.position %}
        {% if 'x' not in printer.toolhead.homed_axes or 'y' not in printer.toolhead.homed_axes %}
            { action_raise_error("Home X and Y first, or use Home All (Z is homed with the nozzle)") }
        {% elif q2_zg_pos.x < q2_zg_x_min or q2_zg_pos.x >= q2_zg_x_lim or q2_zg_pos.y < q2_zg_y_min or q2_zg_pos.y >= q2_zg_y_lim %}
            { action_raise_error("Nozzle not over the plate (X" ~ (q2_zg_pos.x|round(1)) ~ " Y" ~ (q2_zg_pos.y|round(1)) ~ ") - move it over the plate or use Home All") }
        {% endif %}
        G28 Z
    {% else %}

    M204 S10000
    M220 S100
        G1 Z20 F600
    {% endif %}
    M204 S10000   
    G90
        G1 Z20 F600
    {% endif %}
    M204 S10000   
    G90
    {% endif %}

